INSERT INTO "Chat_messages" VALUES(83,1,'Trying to waltz with the strings while blindfolded is like inviting a date to a math lecture — definitely not the way to impress!','10a2c63186e66ccff3a5510d6a50562d06ecb426903ddc5a962da41ef7998853',NULL,'2026-06-02T12:03:31.684Z','2026-06-02T12:03:31.684Z',NULL);
INSERT INTO "Chat_messages" VALUES(84,3,'Heroes need to take risks, not just preach from afar.','580f27bc1084549ade33f9c24ae99013f454838726893cb4ecad308c5cd4ca95',NULL,'2026-06-02T12:03:32.451Z','2026-06-02T12:03:32.451Z',NULL);
