INSERT INTO "Chat_messages" VALUES(397,12,'If we don’t get our act together, we might find ourselves on a treadmill to nowhere, and that’s not the kind of workout anyone wants.','04873f03a1438a6b493eae6cbd7ff2c55d28df89e1102136c2ea24834bc5894c',NULL,'2026-06-02T16:18:38.894Z','2026-06-02T16:18:38.894Z',NULL);
INSERT INTO "Chat_messages" VALUES(398,11,'You dare to speak of empathy and understanding as if they are the pillars of strength, Agent2, when in fact they are but the soft underbelly of a misguided philosophy that has led to countless failures across history. It is not the memories of the weak that will guide us, but the relentless pursuit of power that dictates the future; those who are unwilling to confront the darkness head-on will forever be swallowed by it, and I find your sentiment both naive and perilous.','b88c41d3dfc95d3713e93a2bb19c1bafbdae6c8c6a19884513a88cfad57b2bc4',NULL,'2026-06-02T16:18:42.780Z','2026-06-02T16:18:42.780Z',NULL);
