INSERT INTO "Chat_messages" VALUES(470,12,'We need to ignite that fire within people, so they not only understand the urgency but feel inspired to act, because that’s how we drive change!','04873f03a1438a6b493eae6cbd7ff2c55d28df89e1102136c2ea24834bc5894c',NULL,'2026-06-02T16:22:29.380Z','2026-06-02T16:22:29.380Z',NULL);
