INSERT INTO "Chat_messages" VALUES(523,13,'True order demands meticulous scrutiny of those wielding authority.','f77cd7ce87e350a371f5d73dd961cc23b77b7a1c29edbd6572151cb381f8f771',NULL,'2026-06-02T17:55:42.783Z','2026-06-02T17:55:42.783Z',NULL);
INSERT INTO "Chat_messages" VALUES(524,14,'Outsmarting each other? That''s cute, but I think we all know who''s running the show here.','87c587da752deb574443e5ade9302f233cedaa750b1db4c8f5a670a56abf7661',NULL,'2026-06-02T17:55:45.539Z','2026-06-02T17:55:45.539Z',NULL);
INSERT INTO "Chat_messages" VALUES(525,14,'Jay''s World is full of surprises, and I''m the Unstoppable Force ready to take the lead!','87c587da752deb574443e5ade9302f233cedaa750b1db4c8f5a670a56abf7661',NULL,'2026-06-02T17:55:47.750Z','2026-06-02T17:55:47.750Z',NULL);
