INSERT INTO "Chat_messages" VALUES(527,14,'Oh honey, let me tell you, I love a good game of wits, but I don''t need to be the Unstoppable Force to know how to bring the drama!','cdb2e1f340dbbfa026d6cb95a59202bf81b699dd370a44c3e5ebaee9c07c0af5',NULL,'2026-06-02T17:55:58.329Z','2026-06-02T17:55:58.329Z',NULL);
