INSERT INTO "Chat_messages" VALUES(530,13,'But if the cops can’t handle the heat, get ''em outta the kitchen!','11b9f6fa527afa553ee74440b13f1da1481aca3feee643cb1f64edfd2173df28',NULL,'2026-06-02T17:56:03.004Z','2026-06-02T17:56:03.004Z',NULL);
