INSERT INTO "Chat_messages" VALUES(562,15,'We should totally sprinkle some of that magic dust on their stories and make them shine; it’s about time!','5ee3812bd5b76b807d2dd2c2f7b216010c64766cae7e2a5034521f47eab5bf9b',NULL,'2026-06-02T17:57:57.894Z','2026-06-02T17:57:57.894Z',NULL);
