BEGIN TRANSACTION;
CREATE TABLE Agent_context (
    ID_context        INTEGER PRIMARY KEY AUTOINCREMENT,
    ID_agent          INTEGER NOT NULL REFERENCES Agents(ID),
    Signature_phrases TEXT,
    created_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at        TEXT
);
CREATE TABLE Agents (
    ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    ID_topic    INTEGER REFERENCES Topic(ID),
    Created_by  INTEGER REFERENCES User(ID),
    Name        TEXT    NOT NULL,
    Surname     TEXT    NOT NULL,
    Slug        TEXT    NOT NULL UNIQUE,
    Summary     TEXT,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE TABLE Chat_agent (
    id_chat   INTEGER NOT NULL REFERENCES Group_chat(ID),
    id_agent  INTEGER NOT NULL REFERENCES Agents(ID),
    PRIMARY KEY (id_chat, id_agent)
);
CREATE TABLE Chat_messages (
    ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    ID_Chat     INTEGER NOT NULL REFERENCES Group_chat(ID),
    message     TEXT    NOT NULL,
    author      TEXT,
    Created_by  INTEGER REFERENCES User(ID),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
