CREATE TABLE Group_chat (
    ID            INTEGER PRIMARY KEY AUTOINCREMENT,
    ID_topic      INTEGER NOT NULL REFERENCES Topic(ID),
    Created_by    INTEGER REFERENCES User(ID),
    status        TEXT    NOT NULL DEFAULT 'pending',
    author_map    TEXT,
    speaker_stats TEXT,
    is_judged     INTEGER NOT NULL DEFAULT 0,
    report        TEXT,
    created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at    TEXT
);
CREATE TABLE Judge_evaluation (
    ID_judge               INTEGER NOT NULL REFERENCES Judges(ID),
    ID_chat                INTEGER NOT NULL REFERENCES Group_chat(ID),
    persona_identification TEXT,
    rag_candidates         TEXT,
    group_fidelity_score   INTEGER,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT,
    PRIMARY KEY (ID_judge, ID_chat)
);
CREATE TABLE Judges (
    ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    Role        TEXT    NOT NULL,
    name        TEXT,
    Temperature REAL,
    Guess       TEXT,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE TABLE RefreshToken (
    ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    User_ID     INTEGER NOT NULL REFERENCES User(ID),
    Token_Hash  TEXT    NOT NULL UNIQUE,
    Expires_At  TEXT    NOT NULL,
    Created_At  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    Revoked_At  TEXT
);
CREATE TABLE Topic (
    ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    Title       TEXT    NOT NULL UNIQUE,
    Description TEXT,
    Created_by  INTEGER REFERENCES User(ID),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE TABLE User (
    ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    Username    TEXT    NOT NULL UNIQUE,
    Password    TEXT    NOT NULL,
    Name        TEXT    NOT NULL,
    Surname     TEXT    NOT NULL,
    Role        TEXT    NOT NULL DEFAULT 'common',
    Email       TEXT    NOT NULL UNIQUE,
    Slug        TEXT    NOT NULL UNIQUE,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE TRIGGER user_updated_at
AFTER UPDATE ON User
BEGIN
    UPDATE User
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID = NEW.ID;
END;
CREATE TRIGGER topic_updated_at
AFTER UPDATE ON Topic
BEGIN
    UPDATE Topic
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID = NEW.ID;
END;
CREATE TRIGGER agents_updated_at
AFTER UPDATE ON Agents
BEGIN
    UPDATE Agents
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID = NEW.ID;
END;
CREATE TRIGGER agent_context_updated_at
AFTER UPDATE ON Agent_context
BEGIN
    UPDATE Agent_context
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID_context = NEW.ID_context;
END;
CREATE TRIGGER group_chat_updated_at
AFTER UPDATE ON Group_chat
BEGIN
    UPDATE Group_chat
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID = NEW.ID;
END;
CREATE TRIGGER chat_messages_updated_at
AFTER UPDATE ON Chat_messages
BEGIN
    UPDATE Chat_messages
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID = NEW.ID;
END;
CREATE TRIGGER judges_updated_at
AFTER UPDATE ON Judges
BEGIN
    UPDATE Judges
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID = NEW.ID;
END;
CREATE TRIGGER judge_evaluation_updated_at
AFTER UPDATE ON Judge_evaluation
BEGIN
    UPDATE Judge_evaluation
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE ID_judge = NEW.ID_judge AND ID_chat = NEW.ID_chat;
END;
CREATE UNIQUE INDEX idx_judges_name ON Judges(name) WHERE name IS NOT NULL;
